mapper.select:
SELECT id as projectId, title, goal_amount as goalAmount, current_amount as currentAmount, end_at as endAt, status, created_at as createdAt FROM project
AND status IN
#{status}
AND category_id = #{categoryId}
AND (created_at < #{cursorCreatedAt} OR (created_at = #{cursorCreatedAt} AND id < #{cursorId}))
ORDER BY created_at DESC, id DESC LIMIT #{limit}

